import casadi
import pybamm


class TestSymbolToCasadiExceptionDiversityQA:
    def _convert(self, symbol, *, t=None, y=None, y_dot=None, inputs=None):
        try:
            return symbol.to_casadi(t=t, y=y, y_dot=y_dot, inputs=inputs)
        except Exception:
            return None

    def test_case_01(self):
        self._convert(pybamm.Scalar(2))

    def test_case_02(self):
        y = casadi.MX.sym("y", 4)
        self._convert(pybamm.sin(pybamm.StateVector(slice(0, 2))) + 3, y=y)

    def test_case_03(self):
        self._convert(pybamm.StateVector(slice(0, 2)))

    def test_case_04(self):
        y = casadi.MX.sym("y", 4)
        self._convert(pybamm.StateVectorDot(slice(0, 2)), y=y)

    def test_case_05(self):
        self._convert(pybamm.Variable("x"))

    def test_case_06(self):
        u = casadi.MX.sym("u")
        self._convert(pybamm.InputParameter("u"), inputs={"u": u})

    def test_case_07(self):
        self._convert(pybamm.InputParameter("u"), inputs={})

    def test_case_08(self):
        y = casadi.MX.sym("y", 4)
        symbol = pybamm.NumpyConcatenation(
            pybamm.Scalar(1), pybamm.StateVector(slice(0, 2))
        )
        self._convert(symbol, y=y)

    def test_case_09(self):
        y = casadi.MX.sym("y", 4)
        self._convert(pybamm.maximum(pybamm.StateVector(slice(0, 2)), 1), y=y)

    def test_case_10(self):
        c = pybamm.Variable("c", domain="negative electrode")
        self._convert(pybamm.grad(c))

#
# Convert a PyBaMM expression tree to a CasADi expression tree
#
from __future__ import annotations

import casadi
import numpy as np
from scipy import interpolate, special

import pybamm


class CasadiConverter:
    def __init__(self, casadi_symbols=None):
        self._casadi_symbols = casadi_symbols or {}

        pybamm.citations.register("Andersson2019")

    def convert(
        self,
        symbol: pybamm.Symbol,
        t: casadi.MX,
        y: casadi.MX,
        y_dot: casadi.MX,
        inputs: dict | None,
    ) -> casadi.MX:
        """
        This function recurses down the tree, converting the PyBaMM expression tree to
        a CasADi expression tree

        Parameters
        ----------
        symbol : :class:`pybamm.Symbol`
            The symbol to convert
        t : :class:`casadi.MX`
            A casadi symbol representing time
        y : :class:`casadi.MX`
            A casadi symbol representing state vectors
        y_dot : :class:`casadi.MX`
            A casadi symbol representing time derivatives of state vectors
        inputs : dict
            A dictionary of casadi symbols representing parameters

        Returns
        -------
        :class:`casadi.MX`
            The converted symbol
        """
        try:
            return self._casadi_symbols[symbol]
        except KeyError:
            # Change inputs to empty dictionary if it's None
            inputs = inputs or {}
            casadi_symbol = self._convert(symbol, t, y, y_dot, inputs)
            self._casadi_symbols[symbol] = casadi_symbol

            return casadi_symbol

    def _convert(self, symbol, t, y, y_dot, inputs):
        """See :meth:`CasadiConverter.convert()`."""
        if isinstance(
            symbol,
            pybamm.Scalar | pybamm.Array | pybamm.Time | pybamm.InputParameter,
        ):
            return casadi.MX(symbol.evaluate(t, y, y_dot, inputs))

        elif isinstance(symbol, pybamm.StateVector):
            if y is None:
                raise ValueError("Must provide a 'y' for converting state vectors")
            return casadi.vertcat(*[y[y_slice] for y_slice in symbol.y_slices])

        elif isinstance(symbol, pybamm.StateVectorDot):
            if y_dot is None:
                raise ValueError("Must provide a 'y_dot' for converting state vectors")
            return casadi.vertcat(*[y_dot[y_slice] for y_slice in symbol.y_slices])

        elif isinstance(symbol, pybamm.BinaryOperator):
            left, right = symbol.children
            # process children
            converted_left = self.convert(left, t, y, y_dot, inputs)
            converted_right = self.convert(right, t, y, y_dot, inputs)

            if isinstance(symbol, pybamm.Modulo):
                return casadi.fmod(converted_left, converted_right)
            if isinstance(symbol, pybamm.Minimum):
                return casadi.fmin(converted_left, converted_right)
            if isinstance(symbol, pybamm.Maximum):
                return casadi.fmax(converted_left, converted_right)

            # _binary_evaluate defined in derived classes for specific rules
            return symbol._binary_evaluate(converted_left, converted_right)

        elif isinstance(symbol, pybamm.UnaryOperator):
            converted_child = self.convert(symbol.child, t, y, y_dot, inputs)
            if isinstance(symbol, pybamm.AbsoluteValue):
                return casadi.fabs(converted_child)
            if isinstance(symbol, pybamm.Floor):
                return casadi.floor(converted_child)
            if isinstance(symbol, pybamm.Ceiling):
                return casadi.ceil(converted_child)
            return symbol._unary_evaluate(converted_child)

        elif isinstance(symbol, pybamm.Function):
            converted_children = [
                self.convert(child, t, y, y_dot, inputs) for child in symbol.children
            ]
            # Special functions
            if symbol.function == np.min:
                return casadi.mmin(*converted_children)
            elif symbol.function == np.max:
                return casadi.mmax(*converted_children)
            elif symbol.function == np.abs:
                return casadi.fabs(*converted_children)
            elif symbol.function == np.sqrt:
                return casadi.sqrt(*converted_children)
            elif symbol.function == np.sin:
                return casadi.sin(*converted_children)
            elif symbol.function == np.arcsinh:
                return casadi.arcsinh(*converted_children)
            elif symbol.function == np.arccosh:
                return casadi.arccosh(*converted_children)
            elif symbol.function == np.tanh:
                return casadi.tanh(*converted_children)
            elif symbol.function == np.cosh:
                return casadi.cosh(*converted_children)
            elif symbol.function == np.sinh:
                return casadi.sinh(*converted_children)
            elif symbol.function == np.cos:
                return casadi.cos(*converted_children)
            elif symbol.function == np.exp:
                return casadi.exp(*converted_children)
            elif symbol.function == np.log:
                return casadi.log(*converted_children)
            elif symbol.function == np.sign:
                return casadi.sign(*converted_children)
            elif symbol.function == special.erf:
                return casadi.erf(*converted_children)
            elif isinstance(symbol, pybamm.Interpolant):
                if symbol.interpolator == "linear":
                    solver = "linear"
                elif symbol.interpolator == "cubic":
                    solver = "bspline"
                elif symbol.interpolator == "pchip":
                    x_np = np.array(symbol.x[0])
                    y_np = np.array(symbol.y)
                    pchip_interp = interpolate.PchipInterpolator(x_np, y_np)
                    d_np = pchip_interp.derivative()(x_np)
                    x = converted_children[0]

                    def hermite_poly(i):
                        x0 = x_np[i]
                        x1 = x_np[i + 1]
                        h_val = x1 - x0
                        h_val_mx = casadi.MX(h_val)
                        y0 = casadi.MX(y_np[i])
                        y1 = casadi.MX(y_np[i + 1])
                        d0 = casadi.MX(d_np[i])
                        d1 = casadi.MX(d_np[i + 1])
                        xn = (x - x0) / h_val_mx
                        h00 = 2 * xn**3 - 3 * xn**2 + 1
                        h10 = xn**3 - 2 * xn**2 + xn
                        h01 = -2 * xn**3 + 3 * xn**2
                        h11 = xn**3 - xn**2
                        return (
                            h00 * y0
                            + h10 * h_val_mx * d0
                            + h01 * y1
                            + h11 * h_val_mx * d1
                        )

                    # Build piecewise polynomial for points inside the domain.
                    inside = casadi.MX.zeros(x.shape)
                    for i in range(len(x_np) - 1):
                        cond = casadi.logic_and(x >= x_np[i], x <= x_np[i + 1])
                        inside = casadi.if_else(cond, hermite_poly(i), inside)

                    # Extrapolation:
                    left = hermite_poly(0)  # For x < x_np[0]
                    right = hermite_poly(len(x_np) - 2)  # For x > x_np[-1]

                    # if greater than the maximum, use right; otherwise, use the piecewise value.
                    result = casadi.if_else(
                        x < x_np[0], left, casadi.if_else(x > x_np[-1], right, inside)
                    )
                    return result
                else:  # pragma: no cover
                    raise NotImplementedError(
                        f"Unknown interpolator: {symbol.interpolator}"
                    )

                if len(converted_children) == 1:
                    if solver == "linear":
                        test = casadi.MX.interpn_linear(
                            symbol.x, symbol.y.flatten(), converted_children
                        )
                        if test.shape[0] == 1 and test.shape[1] > 1:
                            # for some reason, pybamm.Interpolant always returns a column vector, so match that
                            test = test.T
                        return test
                    elif solver == "bspline":
                        bspline = interpolate.make_interp_spline(
                            symbol.x[0], symbol.y, k=3
                        )
                        knots = [bspline.t]
                        coeffs = bspline.c.flatten()
                        degree = [bspline.k]
                        m = len(coeffs) // len(symbol.x[0])
                        f = casadi.Function.bspline(
                            symbol.name, knots, coeffs, degree, m
                        )
                        return f(converted_children[0])
                    else:
                        return casadi.interpolant(
                            "LUT", solver, symbol.x, symbol.y.flatten()
                        )(*converted_children)
                elif len(converted_children) in [2, 3]:
                    if solver == "linear":
                        return casadi.MX.interpn_linear(
                            symbol.x,
                            symbol.y.ravel(order="F"),
                            converted_children,
                        )
                    elif solver == "bspline" and len(converted_children) == 2:
                        bspline = interpolate.RectBivariateSpline(
                            symbol.x[0], symbol.x[1], symbol.y
                        )
                        [tx, ty, c] = bspline.tck
                        [kx, ky] = bspline.degrees
                        knots = [tx, ty]
                        coeffs = c
                        degree = [kx, ky]
                        m = 1
                        f = casadi.Function.bspline(
                            symbol.name, knots, coeffs, degree, m
                        )
                        return f(casadi.hcat(converted_children).T).T
                    else:
                        LUT = casadi.interpolant(
                            "LUT", solver, symbol.x, symbol.y.ravel(order="F")
                        )
                        res = LUT(casadi.hcat(converted_children).T).T
                        return res
                else:  # pragma: no cover
                    raise ValueError(
                        f"Invalid converted_children count: {len(converted_children)}"
                    )

            elif symbol.function.__name__.startswith("elementwise_grad_of_"):
                differentiating_child_idx = int(symbol.function.__name__[-1])
                # Create dummy symbolic variables in order to differentiate using CasADi
                dummy_vars = [
                    casadi.MX.sym("y_" + str(i)) for i in range(len(converted_children))
                ]
                func_diff = casadi.gradient(
                    symbol.differentiated_function(*dummy_vars),
                    dummy_vars[differentiating_child_idx],
                )
                # Create function and evaluate it using the children
                casadi_func_diff = casadi.Function("func_diff", dummy_vars, [func_diff])
                return casadi_func_diff(*converted_children)

        return casadi_func_diff(*converted_children)
    # Other functions
    else:
        return symbol._function_evaluate(converted_children)
elif isinstance(symbol, pybamm.Concatenation):
    converted_children = [
        self.convert(child, t, y, y_dot, inputs) for child in symbol.children
    ]
    if isinstance(symbol, pybamm.NumpyConcatenation | pybamm.SparseStack):
        return casadi.vertcat(*converted_children)
    # DomainConcatenation specifies a particular ordering for the concatenation,
    # which we must follow
    elif isinstance(symbol, pybamm.DomainConcatenation):
        slice_starts = []
        all_child_vectors = []
        for i in range(symbol.secondary_dimensions_npts):
            child_vectors = []
            for child_var, slices in zip(
                converted_children, symbol._children_slices, strict=False
            ):
                for child_dom, child_slice in slices.items():
                    slice_starts.append(symbol._slices[child_dom][i].start)
                    child_vectors.append(
                        child_var[child_slice[i].start : child_slice[i].stop]
                    )
            all_child_vectors.extend(
                [
                    v
                    for _, v in sorted(
                        zip(slice_starts, child_vectors, strict=False)
                    )
                ]
            )
        return casadi.vertcat(*all_child_vectors)

else:
    raise TypeError(
        f"Cannot convert symbol of type '{type(symbol)}' to CasADi. Symbols must all be "
        "'linear algebra' at this stage."
    )

#
# Parameter classes
#
from __future__ import annotations

import numbers

import numpy as np
import numpy.typing as npt
import scipy.sparse

import pybamm
from pybamm.type_definitions import DomainType


class InputParameter(pybamm.Symbol):
    """
    A node in the expression tree representing an input parameter.

    This node's value can be set at the point of solving, allowing parameter estimation
    and control

    Parameters
    ----------
    name : str
        name of the node
    domain : iterable of str, or str
        list of domains over which the node is valid (empty list indicates the symbol
        is valid over all domains)
    expected_size : int
        The size of the input parameter expected, defaults to 1 (scalar input)
    """

    def __init__(
        self,
        name: str,
        domain: DomainType = None,
        expected_size: int | None = None,
    ) -> None:
        # Expected size defaults to 1 if no domain else None (gets set later)
        if expected_size is None:
            if domain is None:
                expected_size = 1
            else:
                expected_size = None
        self._expected_size = expected_size
        super().__init__(name, domain=domain)

    @classmethod
    def _from_json(cls, snippet: dict):
        return cls(
            snippet["name"],
            domain=snippet["domain"],
            expected_size=snippet["expected_size"],
        )

    def create_copy(
        self,
        new_children=None,
        perform_simplifications=True,
    ) -> pybamm.InputParameter:
        """See :meth:`pybamm.Symbol.new_copy()`."""
        new_input_parameter = InputParameter(
            self.name, self.domain, expected_size=self._expected_size
        )
        return new_input_parameter

    def _evaluate_for_shape(self):
        """
        Returns the scalar 'NaN' to represent the shape of a parameter.
        See :meth:`pybamm.Symbol.evaluate_for_shape()`
        """
        if self._expected_size is None:
            return pybamm.evaluate_for_shape_using_domain(self.domains)
        elif self._expected_size == 1:
            return np.nan
        else:
            return np.nan * np.ones((self._expected_size, 1))

    def _jac(self, variable: pybamm.StateVector) -> pybamm.Matrix:
        """See :meth:`pybamm.Symbol._jac()`."""
        n_variable = variable.evaluation_array.count(True)
        nan_vector = self._evaluate_for_shape()
        if isinstance(nan_vector, numbers.Number):
            n_self = 1
        else:
            n_self = nan_vector.shape[0]
        zero_matrix = scipy.sparse.csr_matrix((n_self, n_variable))
        return pybamm.Matrix(zero_matrix)

    def _base_evaluate(
        self,
        t: float | None = None,
        y: npt.NDArray[np.float64] | None = None,
        y_dot: npt.NDArray[np.float64] | None = None,
        inputs: dict | str | None = None,
    ):
        # inputs should be a dictionary
        # convert 'None' to empty dictionary for more informative error
        if inputs is None:
            inputs = {}
        if not isinstance(inputs, dict):
            # if the special input "shape test" is passed, just return NaN
            if inputs == "shape test":
                return self.evaluate_for_shape()
            raise TypeError("inputs should be a dictionary")
        try:
            input_eval = inputs[self.name]
        # raise more informative error if can't find name in dict
        except KeyError as error:
            raise KeyError(f"Input parameter '{self.name}' not found") from error

        if isinstance(input_eval, numbers.Number):
            input_size = 1
            input_ndim = 0
        else:
            input_size = input_eval.shape[0]
            input_ndim = len(input_eval.shape)
        if input_size == self._expected_size:
            if input_ndim == 1:
                return input_eval[:, np.newaxis]
            else:
                return input_eval
        else:
            raise ValueError(
                f"Input parameter '{self.name}' was given an object of size '{input_size}'"
                + f" but was expecting an object of size '{self._expected_size}'."
            )

    def to_json(self):
        """
        Method to serialise an InputParameter object into JSON.
        """

        json_dict = {
            "name": self.name,
            "id": self.id,
            "domain": self.domain,
            "expected_size": self._expected_size,
        }

        return json_dict

#
# Scalar class
#
from __future__ import annotations

from typing import Literal

import numpy as np
import numpy.typing as npt
import sympy

import pybamm
from pybamm.type_definitions import Numeric


class Scalar(pybamm.Symbol):
    """
    A node in the expression tree representing a scalar value.

    Parameters
    ----------
    value : numeric
        the value returned by the node when evaluated
    name : str, optional
        the name of the node. Defaulted to ``str(value)`` if not provided


    """

    def __init__(
        self,
        value: Numeric,
        name: str | None = None,
    ) -> None:
        # set default name if not provided
        self.value = value
        if name is None:
            name = str(self.value)

        super().__init__(name)

    @classmethod
    def _from_json(cls, snippet: dict):
        return cls(snippet["value"], name=snippet["name"])

    def __str__(self):
        return str(self.value)

    @property
    def value(self):
        """The value returned by the node when evaluated."""
        return self._value

    # address numpy 1.25 deprecation warning: array should have ndim=0 before conversion
    @value.setter
    def value(self, value):
        self._value = (
            np.float64(value.item())
            if isinstance(value, np.ndarray)
            else np.float64(value)
        )

    def set_id(self):
        """See :meth:`pybamm.Symbol.set_id()`."""
        # We must include the value in the hash, since different scalars can be
        # indistinguishable by class and name alone
        self._id = hash((self.__class__, str(self.value)))

    def _base_evaluate(
        self,
        t: float | None = None,
        y: npt.NDArray[np.float64] | None = None,
        y_dot: npt.NDArray[np.float64] | None = None,
        inputs: dict | str | None = None,
    ):
        """See :meth:`pybamm.Symbol._base_evaluate()`."""
        return self._value

    def _jac(self, variable: pybamm.Variable) -> pybamm.Scalar:
        """See :meth:`pybamm.Symbol._jac()`."""
        return pybamm.Scalar(0)

    def create_copy(
        self,
        new_children=None,
        perform_simplifications=True,
    ):
        """See :meth:`pybamm.Symbol.new_copy()`."""
        if new_children is None or len(new_children) == 0:
            return Scalar(self.value, self.name)
        else:
            raise ValueError(
                f"Cannot create a copy of a scalar with new children: {new_children}"
            )

    def is_constant(self) -> Literal[True]:
        """See :meth:`pybamm.Symbol.is_constant()`."""
        return True

    def to_equation(self):
        """Returns the value returned by the node when evaluated."""
        if self.print_name is not None:
            return sympy.Symbol(self.print_name)
        else:
            return self.value

    def to_json(self):
        """
        Method to serialise a Symbol object into JSON.
        """

        json_dict = {"name": self.name, "id": self.id, "value": self.value}

        return json_dict


class Constant(Scalar):
    """
    A node in the expression tree representing a named constant value. This is a subclass of
    :class:`pybamm.Scalar` and is used to represent named constants such as :math:`R`, :math:`F`,
    and :math:`k_b`. Counterintuitively, the "is_constant" method is set to False, so that
    named constants are not simplified when constructed.

    Parameters
    ----------
    value : numeric
        the value returned by the node when evaluated
    name : str
        the name of the node
    """

    def __init__(self, value: Numeric, name: str):
        super().__init__(value, name)

    def is_constant(self) -> Literal[True]:
        """
        The value is constant, but setting this to False makes sure we retain named constants
        in the expression tree. For example, `pybamm.constants.R + 2` should not be
        simplified to `10.314462618` until after the expression is evaluated. See :meth:`pybamm.Symbol.is_constant()`.
        """
        return False

    def __str__(self):
        return str(self.name)

        List of boolean arrays representing slices. Default is None, in which case the
        evaluation_array is computed from y_slices.
    """

    def __init__(
        self,
        *y_slices: slice,
        name: str | None = None,
        domain: DomainType = None,
        auxiliary_domains: AuxiliaryDomainType = None,
        domains: DomainsType = None,
        evaluation_array: list[bool] | None = None,
    ):
        super().__init__(
            *y_slices,
            base_name="y",
            name=name,
            domain=domain,
            auxiliary_domains=auxiliary_domains,
            domains=domains,
            evaluation_array=evaluation_array,
        )

    def _base_evaluate(
        self,
        t: float | None = None,
        y: npt.NDArray[np.float64] | None = None,
        y_dot: npt.NDArray[np.float64] | None = None,
        inputs: dict | str | None = None,
    ):
        """See :meth:`pybamm.Symbol._base_evaluate()`."""
        if y is None:
            raise TypeError("StateVector cannot evaluate input 'y=None'")
        if y.shape[0] < len(self.evaluation_array):
            raise ValueError(
                "y is too short, so value with slice is smaller than expected"
            )

        out = (y[: len(self._evaluation_array)])[self._evaluation_array]
        if isinstance(out, np.ndarray) and out.ndim == 1:
            out = out[:, np.newaxis]
        return out

    def diff(self, variable: pybamm.Symbol):
        if variable == self:
            return pybamm.Scalar(1)
        if variable == pybamm.t:
            return StateVectorDot(
                *self._y_slices,
                name=self.name + "'",
                domains=self.domains,
                evaluation_array=self.evaluation_array,
            )
        else:
            return pybamm.Scalar(0)

    def _jac(self, variable: pybamm.StateVector | pybamm.StateVectorDot):
        if isinstance(variable, pybamm.StateVector):
            return self._jac_same_vector(variable)
        elif isinstance(variable, pybamm.StateVectorDot):
            return self._jac_diff_vector(variable)


class StateVectorDot(StateVectorBase):
    """
    Node in the expression tree that holds a slice to read from the ydot.

    Parameters
    ----------

    y_slice: slice
        the slice of an external ydot to read
    name: str, optional
        the name of the node
    domain : iterable of str, optional
        list of domains the parameter is valid over, defaults to empty list
    auxiliary_domains : dict of str, optional
        dictionary of auxiliary domains
    domains : dict
        A dictionary equivalent to {'primary': domain, auxiliary_domains}. Either
        'domain' and 'auxiliary_domains', or just 'domains', should be provided
        (not both). In future, the 'domain' and 'auxiliary_domains' arguments may be
        deprecated.
    evaluation_array : list, optional
        List of boolean arrays representing slices. Default is None, in which case the
        evaluation_array is computed from y_slices.
    """

    def __init__(
        self,
        *y_slices: slice,
        name: str | None = None,
        domain: DomainType = None,
        auxiliary_domains: AuxiliaryDomainType = None,
        domains: DomainsType = None,
        evaluation_array: list[bool] | None = None,
    ):
        super().__init__(
            *y_slices,
            base_name="y_dot",
            name=name,
            domain=domain,
            auxiliary_domains=auxiliary_domains,
            domains=domains,
            evaluation_array=evaluation_array,
        )

    def _base_evaluate(
        self,
        t: float | None = None,
        y: npt.NDArray[np.float64] | None = None,
        y_dot: npt.NDArray[np.float64] | None = None,
        inputs: dict | str | None = None,
    ):
        """See :meth:`pybamm.Symbol._base_evaluate()`."""
        if y_dot is None:
            raise TypeError("StateVectorDot cannot evaluate input 'y_dot=None'")
        if y_dot.shape[0] < len(self.evaluation_array):
            raise ValueError(
                "y_dot is too short, so value with slice is smaller than expected"
            )

        out = (y_dot[: len(self._evaluation_array)])[self._evaluation_array]
        if isinstance(out, np.ndarray) and out.ndim == 1:
            out = out[:, np.newaxis]
        return out

    def diff(self, variable: pybamm.Symbol):
        if variable == self:
            return pybamm.Scalar(1)
        elif variable == pybamm.t:
            raise pybamm.ModelError(
                "cannot take second time derivative of a state vector"
            )
        else:
            return pybamm.Scalar(0)

    def _jac(self, variable: pybamm.StateVector | pybamm.StateVectorDot):
        if isinstance(variable, pybamm.StateVectorDot):
            return self._jac_same_vector(variable)
        elif isinstance(variable, pybamm.StateVector):
            return self._jac_diff_vector(variable)

